import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.Supplier;

public class Solution {
    record Resultado(String id, String status, int valor) {}

    static class ConflitoIdempotenciaException extends RuntimeException {
        ConflitoIdempotenciaException(String message) { super(message); }
    }

    static class IdempotenciaService {
        private record Registro(String payload, Resultado resultado) {}

        private final Map<String, Registro> registros = new HashMap<>();
        private final Set<String> emAndamento = new HashSet<>();
        private int execucoes = 0;

        Resultado executar(String chave, String payload, Supplier<Resultado> operacao) {
            if (chave == null || chave.isBlank()) throw new IllegalArgumentException("chave obrigatoria");
            if (payload == null || payload.isBlank()) throw new IllegalArgumentException("payload obrigatorio");
            if (operacao == null) throw new IllegalArgumentException("operacao obrigatoria");

            var existente = registros.get(chave);
            if (existente != null) {
                if (!existente.payload().equals(payload)) {
                    throw new ConflitoIdempotenciaException(
                        "chave " + chave + " ja usada com outro payload");
                }
                return existente.resultado();
            }

            if (!emAndamento.add(chave)) {
                throw new IllegalStateException("execucao em andamento para a chave " + chave);
            }
            try {
                Resultado resultado = operacao.get();
                if (resultado == null) {
                    throw new IllegalStateException("operacao devolveu null");
                }
                execucoes++;
                registros.put(chave, new Registro(payload, resultado));
                return resultado;
            } finally {
                emAndamento.remove(chave);
            }
        }

        int execucoes() { return execucoes; }
    }
}

