import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.concurrent.atomic.AtomicInteger;

class SolutionTest {
    private final Solution.IdempotenciaService service = new Solution.IdempotenciaService();

    @Test void repeticaoNaoExecutaDeNovo() {
        var chamadas = new AtomicInteger();
        var esperado = new Solution.Resultado("r1", "OK", 10);

        var a = service.executar("k1", "payload", () -> {
            chamadas.incrementAndGet();
            return esperado;
        });
        var b = service.executar("k1", "payload", () -> {
            chamadas.incrementAndGet();
            return new Solution.Resultado("r2", "OK", 99);
        });

        assertEquals(esperado, a);
        assertEquals(esperado, b);
        assertEquals(1, chamadas.get());
        assertEquals(1, service.execucoes());
    }

    @Test void payloadDiferenteConflita() {
        service.executar("k1", "p1", () -> new Solution.Resultado("r1", "OK", 1));
        var erro = assertThrows(Solution.ConflitoIdempotenciaException.class,
            () -> service.executar("k1", "p2", () -> new Solution.Resultado("r2", "OK", 2)));
        assertTrue(erro.getMessage().contains("payload"));
    }

    @Test void falhaNaoEhCacheada() {
        var chamadas = new AtomicInteger();
        assertThrows(IllegalStateException.class, () -> service.executar("k1", "p", () -> {
            chamadas.incrementAndGet();
            throw new IllegalStateException("falhou");
        }));
        assertEquals(0, service.execucoes());

        var r = service.executar("k1", "p", () -> {
            chamadas.incrementAndGet();
            return new Solution.Resultado("r1", "OK", 1);
        });
        assertEquals("r1", r.id());
        assertEquals(2, chamadas.get());
        assertEquals(1, service.execucoes());
    }

    @Test void resultadoNuloNaoEhAceito() {
        assertThrows(IllegalStateException.class, () -> service.executar("k1", "p", () -> null));
        assertEquals(0, service.execucoes());
        var r = service.executar("k1", "p", () -> new Solution.Resultado("r1", "OK", 1));
        assertEquals("r1", r.id());
    }

    @Test void chavesDiferentesExecutamIndependentes() {
        var r1 = service.executar("k1", "p", () -> new Solution.Resultado("r1", "OK", 1));
        var r2 = service.executar("k2", "p", () -> new Solution.Resultado("r2", "OK", 2));
        assertEquals("r1", r1.id());
        assertEquals("r2", r2.id());
        assertEquals(2, service.execucoes());
    }

    @Test void recursaoComMesmaChaveFalha() {
        assertThrows(IllegalStateException.class, () -> service.executar("k1", "p", () ->
            service.executar("k1", "p", () -> new Solution.Resultado("r2", "OK", 2))));
        assertEquals(0, service.execucoes());

        var r = service.executar("k1", "p", () -> new Solution.Resultado("r1", "OK", 1));
        assertEquals("r1", r.id());
    }

    @Test void validacoes() {
        assertThrows(IllegalArgumentException.class,
            () -> service.executar("", "p", () -> new Solution.Resultado("r", "OK", 1)));
        assertThrows(IllegalArgumentException.class,
            () -> service.executar("k", " ", () -> new Solution.Resultado("r", "OK", 1)));
        assertThrows(IllegalArgumentException.class, () -> service.executar("k", "p", null));
    }
}
